"use client"

/** Clean-room AE dashboard piece. Bars grow from the bottom; the last bar uses the accent. Theme tokens only. */

import { useId, useState } from "react"
import { motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"
import { growTransition } from "@/lib/ae-dash"
import { AeCard, AeEmpty, AeSkeleton } from "@/components/ui/ae/card-shell"

export type BarPoint = { label: string; value: number }

export type BarTrendCardProps = {
  title?: string
  data: BarPoint[]
  ranges?: { value: number; label: string }[]
  defaultRange?: number
  unit?: string
  loading?: boolean
  className?: string
}

const defaultRanges = [
  { value: 3, label: "Últimos 3 meses" },
  { value: 7, label: "Últimos 7 meses" },
]

export function BarTrendCard({ title = "Expedientes cerrados", data, ranges = defaultRanges, defaultRange = 7, unit = "expedientes", loading = false, className }: BarTrendCardProps) {
  const reduce = !!useReducedMotion()
  const selectId = useId()
  const [range, setRange] = useState(defaultRange)
  const shown = data.slice(-range)
  const max = Math.max(1, ...shown.map((point) => point.value))
  return (
    <AeCard
      title={title}
      className={className}
      action={
        <>
          <label htmlFor={selectId} className="sr-only">
            Periodo
          </label>
          <select id={selectId} value={range} onChange={(event) => setRange(Number(event.target.value))} className="h-9 rounded-full border border-input bg-background px-3 text-xs font-medium outline-none focus-visible:ring-2 focus-visible:ring-ring">
            {ranges.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>
        </>
      }
    >
      {loading ? (
        <AeSkeleton rows={4} />
      ) : shown.length === 0 ? (
        <AeEmpty>Sin datos en este periodo.</AeEmpty>
      ) : (
        <figure className="grid gap-2">
          <figcaption className="sr-only">
            {title}: {shown.map((point) => `${point.label} ${point.value} ${unit}`).join(", ")}
          </figcaption>
          <div className="flex h-48 items-end gap-2 sm:gap-3" aria-hidden>
            {shown.map((point, index) => {
              const last = index === shown.length - 1
              return (
                <div key={`${range}-${point.label}`} className="flex h-full min-w-0 flex-1 flex-col items-center justify-end gap-2">
                  <span className={cn("text-xs font-semibold tabular-nums", last ? "text-primary" : "text-muted-foreground")}>{point.value}</span>
                  <motion.div
                    className={cn("w-full max-w-12 rounded-full", last ? "bg-primary shadow-md" : "bg-muted")}
                    style={{ height: `${(point.value / max) * 100}%`, originY: 1 }}
                    initial={{ scaleY: reduce ? 1 : 0 }}
                    animate={{ scaleY: 1 }}
                    transition={growTransition(reduce, index)}
                  />
                  <span className="text-xs text-muted-foreground">{point.label}</span>
                </div>
              )
            })}
          </div>
        </figure>
      )}
    </AeCard>
  )
}

"use client"

/** Clean-room AE dashboard surface. Theme tokens only. */

import { createContext, useContext, type ReactNode } from "react"
import { motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"
import { aeCard, liftOnHover, riseItem, staggerParent } from "@/lib/ae-dash"

export type AeCardProps = {
  title?: ReactNode
  action?: ReactNode
  children: ReactNode
  className?: string
  /** Section label for screen readers when there is no visible title. */
  label?: string
  as?: "section" | "article"
}

const AeOrder = createContext<(() => number) | null>(null)

/** White card with a large radius, soft shadow, staggered rise and hover lift. Put it inside an `AeStagger`. */
export function AeCard({ title, action, children, className, label, as = "section" }: AeCardProps) {
  const reduce = !!useReducedMotion()
  const take = useContext(AeOrder)
  const index = take ? take() : 0
  const Tag = as === "article" ? motion.article : motion.section
  return (
    <Tag
      data-slot="ae-card"
      data-stagger-index={index}
      aria-label={typeof title === "string" ? title : label}
      variants={riseItem(reduce, index)}
      whileHover={liftOnHover(reduce)}
      className={cn(aeCard, "flex min-w-0 flex-col gap-4 p-5 transition-shadow hover:shadow-md", className)}
    >
      {title || action ? (
        <header className="flex min-w-0 flex-wrap items-center justify-between gap-x-3 gap-y-2">
          {title ? <h3 className="min-w-0 text-base font-semibold break-words">{title}</h3> : <span />}
          {action}
        </header>
      ) : null}
      {children}
    </Tag>
  )
}

/** Runs the staggered entrance of every AeCard inside it. */
export function AeStagger({ children, className }: { children: ReactNode; className?: string }) {
  const reduce = !!useReducedMotion()
  const order = { n: 0 }
  // The next index is taken while each AeCard renders. A new object starts every pass,
  // so a later parent render recounts from zero. A ref cannot do this: the lint forbids
  // reading it during render, and the delay has to exist on the first paint.
  const take = () => order.n++
  return (
    // eslint-disable-next-line react-hooks/immutability -- render-time counter, consumed by children during this render
    <AeOrder.Provider value={take}>
      <motion.div
        data-slot="ae-stagger"
        data-reduced={reduce ? "true" : "false"}
        initial="hidden"
        animate="shown"
        variants={staggerParent}
        className={className}
      >
        {children}
      </motion.div>
    </AeOrder.Provider>
  )
}

export function AeEmpty({ children }: { children: ReactNode }) {
  return <p className="rounded-2xl border border-dashed border-border p-6 text-center text-sm text-muted-foreground">{children}</p>
}

export function AeSkeleton({ rows = 3 }: { rows?: number }) {
  return (
    <div role="status" aria-label="Cargando" className="grid gap-3">
      {Array.from({ length: rows }, (_, index) => (
        <div key={index} className="h-6 animate-pulse rounded-full bg-muted motion-reduce:animate-none" />
      ))}
    </div>
  )
}

/**
 * Shared motion and surface helpers for the AE dashboard pieces.
 * Clean-room. Durations only, no colors or theme tokens.
 */
import type { Transition, Variants } from "motion/react"

import { motionPresets, staggerDelaySeconds } from "@/lib/motion"

/** Parent of a staggered entrance. Children use `riseItem` and own the delay. */
export const staggerParent: Variants = {
  hidden: {},
  shown: {},
}

/** Fade and a short rise. Reduced motion keeps a shared opacity fade and drops the rise. */
export function riseItem(reduce: boolean, index = 0): Variants {
  return reduce
    ? { hidden: { opacity: 0 }, shown: { opacity: 1, transition: { duration: motionPresets.duration.instant, delay: 0 } } }
    : {
        hidden: { opacity: 0, y: 8 },
        shown: {
          opacity: 1,
          y: 0,
          transition: {
            duration: motionPresets.duration.standard,
            ease: [...motionPresets.ease.enter],
            delay: staggerDelaySeconds(index),
          },
        },
      }
}

/** Grow transition for bars and stroke draws. Zero when motion is reduced. */
export function growTransition(reduce: boolean, index = 0): Transition {
  return reduce
    ? { duration: 0 }
    : {
        duration: motionPresets.duration.considered * 1.5,
        ease: [...motionPresets.ease.enter],
        delay: staggerDelaySeconds(index, { step: motionPresets.stagger.item }),
      }
}

/** Hover lift for a card. Off when motion is reduced. */
export function liftOnHover(reduce: boolean) {
  return reduce ? undefined : { y: -3, transition: motionPresets.spring.gentle }
}

/** Base card surface: theme card color, very large radius, soft shadow. */
export const aeCard = "rounded-3xl border border-border/60 bg-card text-card-foreground shadow-sm"

/** Spanish compact number, e.g. 12 400 → "12.4 mil". */
export function compactEs(value: number) {
  return new Intl.NumberFormat("es-MX", { notation: "compact", maximumFractionDigits: 1 }).format(value)
}

/** Avatar fallback is muted on muted (about 4.3:1). This lifts it to foreground for AA. */
export const avatarContrast = { avatar: "[&_[data-slot=avatar-fallback]]:text-foreground", overflow: "text-foreground", count: "text-foreground" }

export function initials(name: string) {
  return name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("")
}

/**
 * Timing presets for pieces adapted from Arc UI (MIT).
 * Durations and springs only. No colors, fonts, or theme tokens.
 */
export const motionPresets = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    exit: 0.18,
    standard: 0.24,
    considered: 0.48,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1] as const,
    // Exit decelerates, the same curve as CSS ease-out.
    exit: [0, 0, 0.58, 1] as const,
    standard: [0.22, 1, 0.36, 1] as const,
    inOut: [0.65, 0, 0.35, 1] as const,
  },
  spring: {
    responsive: { type: "spring" as const, stiffness: 520, damping: 38 },
    gentle: { type: "spring" as const, stiffness: 340, damping: 34 },
    snappy: { type: "spring" as const, visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring" as const, visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring" as const, visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { char: 0.016, word: 0.04, line: 0.08, item: 0.035, marketing: 0.12 },
  blur: { subtle: 2, soft: 4, text: 8 },
}

/**
 * Choreography budgets adapted from Emil Kowalski's choreograph skill (MIT).
 * Copyright (c) 2026 Emil Kowalski. https://github.com/emilkowalski/skills
 * Pinned at c8a79627b59d72d764d6ab6f2c87c09a48169833.
 * Product steps stay inside 30–80ms and the group's delay stays under ~300ms.
 * Marketing steps sit in 100–150ms. Later gaps shrink, and items past the cap
 * share the last delay so a long list never waits N times the step.
 */
export const choreography = {
  productStep: 0.05,
  productCeiling: 0.3,
  marketingStep: 0.12,
  marketingCeiling: 0.6,
  cap: 6,
  decay: 0.72,
  resizeMin: 0.15,
  resizeMax: 0.27,
  resizePerPx: 500,
  attentionDelay: 2.5,
  attentionRepeat: 6,
} as const

export function staggerDelaySeconds(
  index: number,
  options?: { step?: number; cap?: number; decay?: number; ceiling?: number },
) {
  const step = options?.step ?? choreography.productStep
  const cap = options?.cap ?? choreography.cap
  const decay = options?.decay ?? choreography.decay
  const ceiling = options?.ceiling ?? (step >= 0.1 ? choreography.marketingCeiling : choreography.productCeiling)
  const slot = Math.max(0, Math.min(Math.floor(index), Math.max(cap, 1) - 1))
  let delay = 0
  for (let i = 0; i < slot; i += 1) delay += step * Math.pow(decay, i)
  return Math.min(delay, ceiling)
}

/** Fade length for a container whose height changed. `clamp(0.15s, Δpx/500, 0.27s)`. */
export function resizeFadeDuration(deltaPx: number) {
  const delta = Math.abs(deltaPx)
  if (!Number.isFinite(delta)) return choreography.resizeMin
  return Math.min(Math.max(delta / choreography.resizePerPx, choreography.resizeMin), choreography.resizeMax)
}
